WITH base AS (SELECT * FROM stores WHERE (store_name LIKE '%Old%' AND city IN ('London', 'Bangkok')) OR MONTH(opened_date) IN (6, 8, 9)), stores_stats AS (SELECT city, SUM(CASE WHEN city = 'Berlin' THEN sqft ELSE 0 END) AS berlin_sqft, MAX(sqft) - MIN(sqft) AS sqft_range FROM base GROUP BY city) SELECT city, berlin_sqft, sqft_range FROM stores_stats WHERE berlin_sqft > 37 ORDER BY city DESC LIMIT 5;
